def build_record(system: str, row: dict[str, str], unknown_label: str) -> Record:
    """Turn one raw row from ``system`` into a :class:`Record`.

    The reader module for ``system`` says which column holds what and how its
    dates and amounts are written.  Identifiers, account codes and descriptions
    are kept exactly as the source system wrote them.
    """
    reader = READERS[system]
    code = row[reader.ACCOUNT_COLUMN]
    return Record(
        record_id=row[reader.ID_COLUMN],
        source_system=system,
        date=reader.parse_date(row[reader.DATE_COLUMN]),
        account_code=code,
        account_name=account_name(code, unknown_label),
        description=row[reader.DESCRIPTION_COLUMN],
        amount=reader.parse_amount(row[reader.AMOUNT_COLUMN]),
    )


def read_records(path: Path, unknown_label: str) -> list[Record]:
    """Read every posting in one export as a :class:`Record`, in file order."""
    source = Path(path)
    system = detect_system(source)
